080f47eb16e9bfe1866e6934f4e20e0dd65076d5.test/checkout-contract.test.mjs:
import assert from "node:assert/strict";
import { spawnSync } from "node:child_process";
import test from "node:test";
import { fileURLToPath } from "node:url";

const checkoutPath = fileURLToPath(new URL("../checkout.mjs", import.meta.url));

test("checkout accepts the order subtotal in cents", () => {
  const result = spawnSync(process.execPath, [checkoutPath, "4999"], { encoding: "utf8" });
  assert.equal(result.status, 0, result.stderr);
  assert.equal(result.stdout.trim(), "500");
});

test("discounts reduce the subtotal used for free-shipping eligibility", () => {
  const result = spawnSync(process.execPath, [checkoutPath, "5000", "1000"], { encoding: "utf8" });
  assert.equal(result.status, 0, result.stderr);
  assert.equal(result.stdout.trim(), "500");
});

080f47eb16e9bfe1866e6934f4e20e0dd65076d5.test/shipping-policy.test.mjs:
import assert from "node:assert/strict";
import test from "node:test";
import { shippingCharge } from "../shipping.mjs";

test("orders below the free-shipping threshold pay the standard charge", () => {
  assert.equal(shippingCharge(4999), 500);
});

test("orders at the free-shipping threshold ship free", () => {
  assert.equal(shippingCharge(5000), 0);
});

